<?php require_once __DIR__.'/../includes/auth.php';if(!empty($_SESSION['admin_id']))redirect('dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM admin_users WHERE email=? AND is_active=1');$s->execute([$email]);$a=$s->fetch();if($email===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$pass===''||strlen($pass)>72){$error='Enter a valid admin email and your password.';}elseif($a&&password_verify($pass,$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];$_SESSION['admin_name']=$a['name'];$_SESSION['admin_email']=$a['email'];$_SESSION['admin_role']=$a['role'];$pdo->prepare('UPDATE admin_users SET last_login_at=NOW() WHERE id=?')->execute([$a['id']]);log_action($pdo,'admin.login','Successful admin login');redirect('dashboard.php');}if(!$error)$error='Email or password is incorrect.';}$pageTitle='Admin login'; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin login · CampusPass</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><section class="auth-wrap"><div class="auth-card"><span class="eyebrow">Staff access</span><h1 class="h2 mt-3">Admin portal</h1><p class="muted">Sign in with your authorised administrator account.</p><?php if(($_GET['setup']??'')==='success'): ?><div class="alert alert-success">Super Admin created. You can sign in now.</div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><form method="post" data-validate novalidate><?=csrf_field()?><div class="mb-3"><label class="form-label" for="email">Admin email</label><input class="form-control" id="email" type="email" name="email" required maxlength="120" autocomplete="username"></div><div class="mb-4"><label class="form-label" for="password">Password</label><input class="form-control" id="password" type="password" name="password" required maxlength="72" autocomplete="current-password"></div><button class="btn btn-primary w-100">Sign in</button></form><a class="d-block text-center mt-3" href="../index.php">Return to website</a></div></section><script src="../assets/js/validation.js"></script></body></html>
